PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?death WHERE {
  VALUES ?film { dbr:Tap_Roots dbr:Thenum_Vayambum }

  # director directly linked via dbo:director or dbp:director (resource form)
  OPTIONAL { ?film dbo:director ?director. }
  OPTIONAL { ?film dbp:director ?director. }

  # If dbp:director is a literal (name), try to match it to a person resource by label
  OPTIONAL {
    ?film dbp:director ?dirLit .
    FILTER(isLiteral(?dirLit))
    ?director rdfs:label ?dirLabelMatch .
    FILTER(LCASE(STR(?dirLabelMatch)) = LCASE(STR(?dirLit)))
  }

  OPTIONAL { ?director dbo:deathDate ?death. }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}
ORDER BY DESC(?death)
LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?death WHERE {
  VALUES ?film { dbr:Tap_Roots dbr:Thenum_Vayambum }

