  }

  # If dbp:director is a literal for Thenum Vayambum, match it to a person resource by label
  OPTIONAL {
    FILTER(?film = dbr:Thenum_Vayambum)
    ?film dbp:director ?dirLit .
    FILTER(isLiteral(?dirLit))
    ?director rdfs:label ?dirLabel .
    FILTER(LCASE(STR(?dirLabel)) = LCASE(STR(?dirLit)))
  }

  OPTIONAL { ?director dbo:deathDate ?death. }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}
ORDER BY DESC(?death)
LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?winnerFilm ?winnerDirector ?deathWinner WHERE {
  {
    # Case: Thenum Vayambum director died after Tap Roots director
    dbr:Tap_Roots dbo:director ?d1 .
    OPTIONAL { dbr:Tap_Roots dbp:director ?tmp1 . FILTER(isIRI(?tmp1)) BIND(?tmp1 AS ?d1) }
    OPTIONAL {
      dbr:Tap_Roots dbp:director ?lit1 .
      FILTER(isLiteral(?lit1))
      ?d1 rdfs:label ?lab1 .
      FILTER(LCASE(STR(?lab1)) = LCASE(STR(?lit1)))
    }
    ?d1 dbo:deathDate ?death1 .

    OPTIONAL { dbr:Thenum_Vayambum dbo:director ?d2 . }
    OPTIONAL { dbr:Thenum_Vayambum dbp:director ?tmp2 . FILTER(isIRI(?tmp2)) BIND(?tmp2 AS ?d2) }
    OPTIONAL {
      dbr:Thenum_Vayambum dbp:director ?lit2 .
      FILTER(isLiteral(?lit2))
      ?d2 rdfs:label ?lab2 .
      FILTER(LCASE(STR(?lab2)) = LCASE(STR(?lit2)))
    }
    ?d2 dbo:deathDate ?death2 .

    FILTER(?death2 > ?death1)
    BIND(dbr:Thenum_Vayambum AS ?winnerFilm)
    BIND(?d2 AS ?winnerDirector)
    BIND(?death2 AS ?deathWinner)
  }
  UNION
  {
    # Case: Tap Roots director died after Thenum Vayambum director
    dbr:Thenum_Vayambum dbo:director ?d2b .
    OPTIONAL { dbr:Thenum_Vayambum dbp:director ?tmp2b . FILTER(isIRI(?tmp2b)) BIND(?tmp2b AS ?d2b) }
    OPTIONAL {
      dbr:Thenum_Vayambum dbp:director ?lit2b .
      FILTER(isLiteral(?lit2b))
      ?d2b rdfs:label ?lab2b .
      FILTER(LCASE(STR(?lab2b)) = LCASE(STR(?lit2b)))
    }
    ?d2b dbo:deathDate ?death2b .

    OPTIONAL { dbr:Tap_Roots dbo:director ?d1b . }
    OPTIONAL { dbr:Tap_Roots dbp:director ?tmp1b . FILTER(isIRI(?tmp1b)) BIND(?tmp1b AS ?d1b) }
    OPTIONAL {
      dbr:Tap_Roots dbp:director ?lit1b .
      FILTER(isLiteral(?lit1b))
      ?d1b rdfs:label ?lab1b .
      FILTER(LCASE(STR(?lab1b)) = LCASE(STR(?lit1b)))
    }
    ?d1b dbo:deathDate ?death1b .

    FILTER(?death1b > ?death2b)
    BIND(dbr:Tap_Roots AS ?winnerFilm)
    BIND(?d1b AS ?winnerDirector)
    BIND(?death1b AS ?deathWinner)
  }
}

